-- gap bool:430:40:1, written by an automated writer
test("breakit Core.Places: a rider's request keeps the driver's own spelling of a map-name place", function()
	local w = T.newWorld()
	local r = T.rider(w, T.TESTCHAR)
	T.settle(w)
	local realInfo = r.env.C_Map.GetMapInfo
	r.env.C_Map.GetMapInfo = function(id)
		if id == 1 then return { name = "Mystery Isle" } end
		return realInfo(id)
	end
	w:addBot(T.ANITA, { spot = "Ratchet" })
	w:inject(T.ANITA, "D~1~mystery isle~1~0~0~5000~~open~1~0~~2.3.1", "CHANNEL")
	w:advance(1)
	T.requestVia(r, "anita lift")
	w:advance(1)
	local line
	for _, e in ipairs(w.whispers) do
		if e.text:find("^WTB summon to ") then line = e.text end
	end
	eq(line, "WTB summon to mystery isle for 50s", "the request keeps the driver's own spelling of the place")
	T.clean(w)
end)

